from AlgorithmImports import *
from datetime import datetime, time, timedelta


class FiveMinuteSpyCallCrossover(QCAlgorithm):
    def initialize(self):
        self.set_time_zone(TimeZones.NEW_YORK)
        self.set_start_date(2023, 4, 1)
        self.set_end_date(2026, 6, 30)
        self.set_cash(100000)

        self.spy = self.add_equity("SPY", Resolution.MINUTE).symbol
        self.securities[self.spy].set_data_normalization_mode(DataNormalizationMode.RAW)

        option = self.add_option("SPY", Resolution.MINUTE)
        self.option_symbol = option.symbol
        option.set_filter(
            lambda universe: universe.include_weeklys()
            .strikes(-200, 200)
            .expiration(timedelta(0), timedelta(90))
        )

        self._closes = RollingWindow[float](21)
        self._pending_signal_end = None

        self._entry_ticket = None
        self._exit_ticket = None
        self._held_contract = None
        self._entry_fill_price = None
        self._block_entries_date = None
        self._spy_liquidation_ticket = None

        consolidator = TradeBarConsolidator(timedelta(minutes=5))
        consolidator.data_consolidated += self._on_five_minute_bar
        self.subscription_manager.add_consolidator(self.spy, consolidator)

    def _on_five_minute_bar(self, sender, bar):
        # This consolidator is fed only by actual minute SPY bars; no bars are
        # synthesized or forward-filled here.
        self._closes.add(float(bar.close))

        # Need 21 completed bars to compare both current and preceding averages.
        if not self._closes.is_ready:
            return

        current_fast = sum(self._closes[i] for i in range(0, 5)) / 5.0
        current_slow = sum(self._closes[i] for i in range(0, 20)) / 20.0
        previous_fast = sum(self._closes[i] for i in range(1, 6)) / 5.0
        previous_slow = sum(self._closes[i] for i in range(1, 21)) / 20.0

        end_time = bar.end_time.time()
        eligible_time = time(9, 45) <= end_time <= time(14, 30)

        if eligible_time and previous_fast <= previous_slow and current_fast > current_slow:
            self._pending_signal_end = bar.end_time

    def on_data(self, data: Slice):
        self._reset_daily_entry_block()
        self._handle_unexpected_spy_position()
        self._handle_expiration_day_exit()
        self._handle_time_stop()
        self._handle_profit_target(data)

        # A signal is considered only in the Slice immediately following its
        # completed five-minute consolidation.
        if self._pending_signal_end is not None:
            self._pending_signal_end = None
            self._try_enter(data)

    def _try_enter(self, data: Slice):
        if self._block_entries_date == self.time.date():
            return

        if self._held_contract is not None and self.portfolio[self._held_contract].invested:
            return

        if self._entry_ticket is not None and self._entry_ticket.status not in (
            OrderStatus.FILLED,
            OrderStatus.CANCELED,
            OrderStatus.INVALID
        ):
            return

        chain = data.option_chains.get(self.option_symbol)
        if chain is None:
            self.debug(f"{self.time}: Entry skipped: no SPY option chain.")
            return

        spy_price = float(self.securities[self.spy].price)
        if spy_price <= 0:
            self.debug(f"{self.time}: Entry skipped: invalid SPY price.")
            return

        minimum_expiry = self.time.date() + timedelta(days=7)
        calls = [
            contract for contract in chain.contracts.values()
            if contract.right == OptionRight.CALL
            and contract.expiry.date() >= minimum_expiry
        ]

        if not calls:
            self.debug(f"{self.time}: Entry skipped: no eligible call expiration.")
            return

        expiry = min(contract.expiry.date() for contract in calls)
        minimum_strike = spy_price * 1.01

        candidates = [
            contract for contract in calls
            if contract.expiry.date() == expiry
            and float(contract.strike) >= minimum_strike
        ]

        if not candidates:
            self.debug(f"{self.time}: Entry skipped: no >=1% OTM call at {expiry}.")
            return

        selected = min(candidates, key=lambda c: (float(c.strike), str(c.symbol)))
        self._entry_ticket = self.market_order(selected.symbol, 1)

        self.debug(
            f"{self.time}: Entry submitted: {selected.symbol}, "
            f"expiry {selected.expiry.date()}, strike {selected.strike}."
        )

    def _handle_profit_target(self, data: Slice):
        if self._held_contract is None or not self.portfolio[self._held_contract].invested:
            return

        if self._exit_order_open() or self._entry_fill_price is None:
            return

        midpoint = self._current_option_midpoint(data, self._held_contract)
        if midpoint is not None and midpoint >= self._entry_fill_price * 1.50:
            self._submit_exit("profit target")

    def _handle_time_stop(self):
        if self._held_contract is None or not self.portfolio[self._held_contract].invested:
            return

        expiry_date = self._held_contract.id.date.date()
        previous_trading_day = self._previous_trading_day(expiry_date)

        if (
            self.time.date() == previous_trading_day
            and self.time.hour == 15
            and self.time.minute == 45
            and not self._exit_order_open()
        ):
            self._submit_exit("15:45 pre-expiration time stop")

    def _handle_expiration_day_exit(self):
        if self._held_contract is None or not self.portfolio[self._held_contract].invested:
            return

        expiry_date = self._held_contract.id.date.date()
        if self.time.date() >= expiry_date:
            self._block_entries_date = self.time.date()
            if not self._exit_order_open():
                self._submit_exit("expiration-day protection")

    def _handle_unexpected_spy_position(self):
        if self.portfolio[self.spy].quantity == 0:
            return

        if (
            self._spy_liquidation_ticket is None
            or self._spy_liquidation_ticket.status in (
                OrderStatus.FILLED,
                OrderStatus.CANCELED,
                OrderStatus.INVALID
            )
        ):
            quantity = -self.portfolio[self.spy].quantity
            self._spy_liquidation_ticket = self.market_order(self.spy, quantity)
            self.debug(
                f"{self.time}: Unexpected SPY exercise/assignment position; "
                f"submitted liquidation for {quantity} shares."
            )

    def _submit_exit(self, reason):
        if self._held_contract is None:
            return

        # Cancel any outstanding order for this contract before placing the exit.
        for order in self.transactions.get_open_orders(self._held_contract):
            self.transactions.cancel_order(order.id)

        quantity = -self.portfolio[self._held_contract].quantity
        if quantity != 0:
            self._exit_ticket = self.market_order(self._held_contract, quantity)
            self.debug(f"{self.time}: Exit submitted ({reason}): {self._held_contract}.")

    def _current_option_midpoint(self, data: Slice, symbol):
        chain = data.option_chains.get(self.option_symbol)
        if chain is None:
            return None

        contract = next(
            (c for c in chain.contracts.values() if c.symbol == symbol),
            None
        )
        if contract is None:
            return None

        bid = float(contract.bid_price)
        ask = float(contract.ask_price)
        if bid <= 0 or ask <= 0:
            return None

        return (bid + ask) / 2.0

    def _exit_order_open(self):
        return (
            self._exit_ticket is not None
            and self._exit_ticket.status not in (
                OrderStatus.FILLED,
                OrderStatus.CANCELED,
                OrderStatus.INVALID
            )
        )

    def _previous_trading_day(self, expiry_date):
        hours = self.securities[self.spy].exchange.hours
        candidate = expiry_date - timedelta(days=1)

        while not hours.is_date_open(datetime.combine(candidate, time.min)):
            candidate -= timedelta(days=1)

        return candidate

    def _reset_daily_entry_block(self):
        if self._block_entries_date is not None and self.time.date() > self._block_entries_date:
            self._block_entries_date = None

    def on_order_event(self, order_event: OrderEvent):
        if self._entry_ticket is not None and order_event.order_id == self._entry_ticket.order_id:
            if order_event.status == OrderStatus.FILLED and order_event.fill_quantity > 0:
                self._held_contract = order_event.symbol
                self._entry_fill_price = float(order_event.fill_price)
                self.debug(
                    f"{self.time}: Entry filled: {order_event.symbol} "
                    f"at {self._entry_fill_price:.2f}."
                )
            elif order_event.status in (OrderStatus.CANCELED, OrderStatus.INVALID):
                self._entry_ticket = None

        if self._exit_ticket is not None and order_event.order_id == self._exit_ticket.order_id:
            if order_event.status == OrderStatus.FILLED:
                self.debug(
                    f"{self.time}: Exit filled: {order_event.symbol} "
                    f"at {order_event.fill_price:.2f}."
                )
                self._held_contract = None
                self._entry_fill_price = None
                self._exit_ticket = None
