from AlgorithmImports import *
from datetime import timedelta


class FiveMinuteSpyCallCrossover(QCAlgorithm):
    def initialize(self):
        self.set_time_zone(TimeZones.NEW_YORK)
        self.set_start_date(2023, 4, 1)
        self.set_end_date(2026, 6, 30)
        self.set_cash(100000)

        self.spy = self.add_equity(
            "SPY",
            Resolution.MINUTE,
            Market.USA,
            fill_forward=False,
            extended_market_hours=False
        ).symbol
        self.securities[self.spy].set_data_normalization_mode(DataNormalizationMode.RAW)

        self.option = self.add_option("SPY", Resolution.MINUTE)
        self.option.set_filter(
            lambda universe: universe.include_weeklys()
            .strikes(-100, 100)
            .expiration(0, 365)
        )
        self.option_symbol = self.option.symbol

        self.closes = RollingWindow[float](20)
        self.previous_fast = None
        self.previous_slow = None

        self.bucket_start = None
        self.bucket_minutes = []
        self.bucket_valid = True

        self.current_slice = None
        self.entry_order_id = None
        self.entry_symbol = None

        self.held_symbol = None
        self.held_expiry = None
        self.entry_fill_price = None
        self.exit_order_ids = set()

        self.no_entry_date = None
        self.spy_flatten_order_id = None

    def on_data(self, data: Slice):
        self.current_slice = data

        self._flatten_unexpected_spy_position()
        self._process_expiration_safety()
        self._clear_closed_option_state()
        self._evaluate_option_exit(data)

        spy_bar = data.bars.get(self.spy)
        if spy_bar is not None:
            self._update_five_minute_builder(spy_bar)

    def _update_five_minute_builder(self, bar: TradeBar):
        minute_start = bar.time.replace(second=0, microsecond=0)
        period_start = minute_start - timedelta(minutes=minute_start.minute % 5)

        if self.bucket_start != period_start:
            self.bucket_start = period_start
            self.bucket_minutes = []
            self.bucket_valid = True

        expected_minute = period_start + timedelta(minutes=len(self.bucket_minutes))
        if minute_start != expected_minute or len(self.bucket_minutes) >= 5:
            self.bucket_valid = False

        self.bucket_minutes.append(bar)

        period_end = period_start + timedelta(minutes=5)
        if bar.end_time == period_end:
            if self.bucket_valid and len(self.bucket_minutes) == 5:
                self._on_five_minute_bar(period_end, self.bucket_minutes[-1].close)

            self.bucket_start = None
            self.bucket_minutes = []
            self.bucket_valid = True

    def _on_five_minute_bar(self, bar_end_time, close):
        self.closes.add(float(close))

        if not self.closes.is_ready:
            return

        fast = sum(self.closes[i] for i in range(5)) / 5.0
        slow = sum(self.closes[i] for i in range(20)) / 20.0

        bullish_cross = (
            self.previous_fast is not None
            and self.previous_fast <= self.previous_slow
            and fast > slow
        )

        self.previous_fast = fast
        self.previous_slow = slow

        if not bullish_cross:
            return

        bar_time = bar_end_time.time()
        if bar_time < time(9, 45) or bar_time > time(14, 30):
            return

        if self.no_entry_date == self.time.date() or not self._can_enter():
            return

        self._select_and_enter_call()

    def _can_enter(self):
        if self.held_symbol is not None:
            return False

        if self.entry_order_id is not None:
            order = self.transactions.get_order_by_id(self.entry_order_id)
            if order is not None and order.status not in (
                OrderStatus.FILLED,
                OrderStatus.CANCELED,
                OrderStatus.INVALID
            ):
                return False

        return True

    def _select_and_enter_call(self):
        if self.current_slice is None:
            self.debug("Entry skipped: no current Slice.")
            return

        chain = self.current_slice.option_chains.get(self.option_symbol)
        if chain is None:
            self.debug("Entry skipped: no SPY option chain.")
            return

        spot = float(self.securities[self.spy].price)
        if spot <= 0:
            self.debug("Entry skipped: invalid SPY price.")
            return

        minimum_expiry = self.time.date() + timedelta(days=7)
        calls = [
            contract for contract in chain
            if contract.right == OptionRight.CALL
            and contract.expiry.date() >= minimum_expiry
        ]

        if not calls:
            self.debug("Entry skipped: no eligible call expiration.")
            return

        selected_expiry = min(contract.expiry.date() for contract in calls)
        minimum_strike = spot * 1.01

        candidates = [
            contract for contract in calls
            if contract.expiry.date() == selected_expiry
            and float(contract.strike) >= minimum_strike
        ]

        if not candidates:
            self.debug("Entry skipped: no eligible OTM call.")
            return

        selected = min(
            candidates,
            key=lambda contract: (float(contract.strike), str(contract.symbol))
        )

        ticket = self.market_order(selected.symbol, 1)
        self.entry_order_id = ticket.order_id
        self.entry_symbol = selected.symbol
        self.debug(
            f"Entry submitted: {selected.symbol} "
            f"expiry {selected.expiry.date()} strike {selected.strike}"
        )

    def _evaluate_option_exit(self, data: Slice):
        if self.held_symbol is None:
            return

        quantity = self.portfolio[self.held_symbol].quantity
        if quantity == 0:
            return

        if (
            self.time.hour == 15
            and self.time.minute == 45
            and self._is_day_before_expiration()
        ):
            self._submit_exit("day-before-expiration time stop")
            return

        if self.entry_fill_price is None:
            return

        chain = data.option_chains.get(self.option_symbol)
        if chain is None:
            return

        held_contract = next(
            (contract for contract in chain if contract.symbol == self.held_symbol),
            None
        )
        if held_contract is None:
            return

        bid = float(held_contract.bid_price)
        ask = float(held_contract.ask_price)
        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= self.entry_fill_price * 1.50:
            self._submit_exit("50% profit target")

    def _is_day_before_expiration(self):
        if self.held_expiry is None:
            return False

        exchange_hours = self.securities[self.spy].exchange.hours
        prior_trading_day = exchange_hours.get_previous_trading_day(self.held_expiry)
        return self.time.date() == prior_trading_day.date()

    def _process_expiration_safety(self):
        if self.held_symbol is None or self.held_expiry is None:
            return

        if self.time.date() >= self.held_expiry.date():
            self.no_entry_date = self.time.date()
            self._submit_exit("expiration safety liquidation")

