    def _update_five_minute_builder(self, bar: TradeBar):
        minute_start = bar.time.replace(second=0, microsecond=0)
        period_start = minute_start - timedelta(minutes=minute_start.minute % 5)

        if self.bucket_start != period_start:
            self.bucket_start = period_start
            self.bucket_minutes = []
            self.bucket_valid = True

        expected_minute = period_start + timedelta(minutes=len(self.bucket_minutes))
        if minute_start != expected_minute or len(self.bucket_minutes) >= 5:
            self.bucket_valid = False

        self.bucket_minutes.append(bar)

        period_end = period_start + timedelta(minutes=5)
        if bar.end_time == period_end:
            if self.bucket_valid and len(self.bucket_minutes) == 5:
                self._on_five_minute_bar(period_end, self.bucket_minutes[-1].close)

            self.bucket_start = None
            self.bucket_minutes = []
            self.bucket_valid = True

    def _on_five_minute_bar(self, bar_end_time, close):
        self.closes.add(float(close))

        if not self.closes.is_ready:
            return

        fast = sum(self.closes[i] for i in range(5)) / 5.0
        slow = sum(self.closes[i] for i in range(20)) / 20.0

        bullish_cross = (
            self.previous_fast is not None
            and self.previous_fast <= self.previous_slow
            and fast > slow
        )

        self.previous_fast = fast
        self.previous_slow = slow

        if not bullish_cross:
            return

        bar_time = bar_end_time.time()
        if bar_time < time(9, 45) or bar_time > time(14, 30):
            return

        if self.no_entry_date == self.time.date() or not self._can_enter():
