            if (end_time.hour > 9 or (end_time.hour == 9 and end_time.minute >= 45)) and \
               (end_time.hour < 14 or (end_time.hour == 14 and end_time.minute <= 30)):
                self.pending_entry_bar_end = end_time

    def OnData(self, data):
        self.HandleUnexpectedSpyPosition()
        self.HandleExpirationProcessing()
        self.HandleMinuteExit(data)

        if self.pending_entry_bar_end is not None:
            signal_time = self.pending_entry_bar_end
            self.pending_entry_bar_end = None

            if signal_time == self.Time:
                self.TryEnter(data)

    def TryEnter(self, data):
        if self.blocked_entry_date == self.Time.date():
            return

        if self.held_option is not None and self.Portfolio[self.held_option].Invested:
            return

        if self.entry_order_id is not None:
            return

        if self.exit_order_id is not None:
            return

        if not data.Bars.ContainsKey(self.spy):
            self.Debug("Skipped entry: no current SPY price.")
            return

        if not data.OptionChains.ContainsKey(self.option_symbol):
            self.Debug("Skipped entry: no option chain in Slice.")
            return

        spy_price = data.Bars[self.spy].Close
        if spy_price <= 0:
            self.Debug("Skipped entry: invalid SPY price.")
            return

        chain = data.OptionChains[self.option_symbol]
        minimum_expiry = self.Time.date() + timedelta(days=7)

        eligible_expiries = sorted({
            contract.Expiry.date()
            for contract in chain.Contracts.Values
            if contract.Right == OptionRight.Call and contract.Expiry.date() >= minimum_expiry
        })

        if not eligible_expiries:
            self.Debug("Skipped entry: no eligible call expiration.")
            return

        selected_expiry = eligible_expiries[0]
        minimum_strike = spy_price * 1.01

        candidates = [
            contract
            for contract in chain.Contracts.Values
            if contract.Right == OptionRight.Call
            and contract.Expiry.date() == selected_expiry
            and contract.Strike >= minimum_strike
        ]

        if not candidates:
            self.Debug("Skipped entry: no qualifying call strike.")
            return

        contract = min(candidates, key=lambda c: (c.Strike, str(c.Symbol)))
        ticket = self.MarketOrder(contract.Symbol, 1)

        if ticket is not None:
            self.entry_order_id = ticket.OrderId
            self.Debug(
                f"Entry submitted: {contract.Symbol} exp {selected_expiry} strike {contract.Strike}."
            )

    def HandleMinuteExit(self, data):
        if self.held_option is None or not self.Portfolio[self.held_option].Invested:
            return

        if self.exit_order_id is not None:
            return

        if self.IsPriorTradingDayAt1545():
            self.SubmitExit("Time-stop exit")
            return

        if self.entry_fill_price is None or self.entry_fill_price <= 0:
            return

        if not data.QuoteBars.ContainsKey(self.held_option):
            return

        quote = data.QuoteBars[self.held_option]
        if quote.Bid is None or quote.Ask is None:
            return

        bid = quote.Bid.Close
        ask = quote.Ask.Close
        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= self.entry_fill_price * 1.50:
            self.SubmitExit("Profit-target exit")

    def HandleExpirationProcessing(self):
        if self.held_option is None or self.held_expiry is None:
            return

        if self.Time.date() >= self.held_expiry.date():
            self.blocked_entry_date = self.Time.date()

            if self.Portfolio[self.held_option].Invested and self.exit_order_id is None:
                self.SubmitExit("Expiration safety exit")

    def IsPriorTradingDayAt1545(self):
        if self.held_expiry is None:
            return False

        if self.Time.hour != 15 or self.Time.minute != 45:
            return False

        prior_day = self.held_expiry.date() - timedelta(days=1)
        exchange_hours = self.Securities[self.spy].Exchange.Hours

        while not exchange_hours.IsDateOpen(prior_day, False):
            prior_day -= timedelta(days=1)

        return self.Time.date() == prior_day

    def SubmitExit(self, reason):
        if self.held_option is None or self.exit_order_id is not None:
            return

        for order in self.Transactions.GetOpenOrders(self.held_option):
            self.Transactions.CancelOrder(order.Id, f"Cancel before {reason}")

        quantity = self.Portfolio[self.held_option].Quantity
        if quantity != 0:
            ticket = self.MarketOrder(self.held_option, -quantity)
            if ticket is not None:
                self.exit_order_id = ticket.OrderId
                self.Debug(f"{reason}: {self.held_option}.")

    def HandleUnexpectedSpyPosition(self):
        spy_quantity = self.Portfolio[self.spy].Quantity
        if spy_quantity != 0:
            self.MarketOrder(self.spy, -spy_quantity)
            self.Debug(f"Unexpected SPY exercise/assignment position liquidated: {spy_quantity} shares.")

    def OnOrderEvent(self, orderEvent):
        if self.entry_order_id == orderEvent.OrderId:
            if orderEvent.Status == OrderStatus.Filled:
                self.held_option = orderEvent.Symbol
                self.held_expiry = orderEvent.Symbol.ID.Date
                self.entry_fill_price = orderEvent.FillPrice
                self.entry_order_id = None
                self.Debug(
                    f"Entry filled: {self.held_option} at {self.entry_fill_price:.2f}."
                )
            elif orderEvent.Status in [OrderStatus.Canceled, OrderStatus.Invalid]:
                self.entry_order_id = None
                self.Debug("Entry order closed without fill.")

        if self.exit_order_id == orderEvent.OrderId:
            if orderEvent.Status == OrderStatus.Filled:
                self.Debug(f"Exit filled: {orderEvent.Symbol} at {orderEvent.FillPrice:.2f}.")
                self.held_option = None
                self.held_expiry = None
                self.entry_fill_price = None
                self.exit_order_id = None
            elif orderEvent.Status in [OrderStatus.Canceled, OrderStatus.Invalid]:
                self.exit_order_id = None
                self.Debug("Exit order closed without fill.")
