        return None

    def IsEntryOrderOpen(self):
        if self.entry_order_id is None:
            return False

        ticket = self.Transactions.GetOrderTicket(self.entry_order_id)
        return self.IsTicketOpen(ticket)

    def IsExitOrderOpen(self):
        return self.IsTicketOpen(self.exit_ticket)

    def IsTicketOpen(self, ticket):
        return ticket is not None and ticket.Status not in [
            OrderStatus.Filled,
            OrderStatus.Canceled,
            OrderStatus.Invalid
        ]
