from AlgorithmImports import *
from datetime import timedelta


class SpyFiveMinuteCallCrossoverAlgorithm(QCAlgorithm):
    def initialize(self):
        self.set_time_zone("America/New_York")
        self.set_start_date(2023, 4, 1)
        self.set_end_date(2026, 6, 30)
        self.set_cash(100000)

        spy_security = self.add_equity(
            "SPY",
            Resolution.MINUTE,
            data_normalization_mode=DataNormalizationMode.RAW
        )
        self.spy = spy_security.symbol

        option = self.add_option("SPY", Resolution.MINUTE)
        option.set_filter(-100, 100, timedelta(days=0), timedelta(days=365))
        self.option_canonical = option.symbol

        self.closes = RollingWindow[float](21)
        self.pending_crossover_end = None

        self.held_contract = None
        self.held_expiry = None
        self.entry_price = None

        self.entry_order_id = None
        self.exit_order_id = None
        self.spy_cleanup_order_id = None
        self.blocked_entry_date = None

        self.five_minute_consolidator = TradeBarConsolidator(timedelta(minutes=5))
        self.five_minute_consolidator.data_consolidated += self._on_five_minute_bar
        self.subscription_manager.add_consolidator(self.spy, self.five_minute_consolidator)

    def on_data(self, data: Slice):
        self._liquidate_unexpected_spy_position()

        if self._has_option_position():
            self._check_expiration_exit()
            self._check_time_stop()
            self._check_profit_target(data)

        if self.pending_crossover_end is not None:
            crossover_end = self.pending_crossover_end
            self.pending_crossover_end = None

            if crossover_end == self.time:
                self._try_enter(data)

    def _on_five_minute_bar(self, bar: TradeBar):
        self.closes.add(float(bar.close))

        # A prior 20-bar slow average requires 21 actual completed bars.
        if self.closes.count < 21:
            return

        current_fast = sum(self.closes[i] for i in range(5)) / 5.0
        current_slow = sum(self.closes[i] for i in range(20)) / 20.0
        previous_fast = sum(self.closes[i] for i in range(1, 6)) / 5.0
        previous_slow = sum(self.closes[i] for i in range(1, 21)) / 20.0

        is_bullish_crossover = (
            previous_fast <= previous_slow
            and current_fast > current_slow
        )

        minutes_after_midnight = bar.end_time.hour * 60 + bar.end_time.minute
        is_entry_time = 9 * 60 + 45 <= minutes_after_midnight <= 14 * 60 + 30

        if is_bullish_crossover and is_entry_time:
            self.pending_crossover_end = bar.end_time

    def _try_enter(self, data: Slice):
        if self.blocked_entry_date == self.time.date():
            return

        if self._has_option_position() or self._has_open_entry_order():
            return

        if self.spy not in data.bars:
            self.debug("Skipped entry: SPY price unavailable in current Slice.")
            return

        if self.option_canonical not in data.option_chains:
            self.debug("Skipped entry: no SPY option chain in current Slice.")
            return

        spy_price = float(data.bars[self.spy].close)
        chain = data.option_chains[self.option_canonical]
        minimum_expiry_date = self.time.date() + timedelta(days=7)

        eligible_expiries = sorted({
            contract.expiry.date()
            for contract in chain
            if contract.expiry.date() >= minimum_expiry_date
        })

        if not eligible_expiries:
            self.debug("Skipped entry: no expiration at least seven calendar days away.")
            return

        selected_expiry = eligible_expiries[0]
        minimum_strike = spy_price * 1.01

        candidates = [
            contract
            for contract in chain
            if contract.right == OptionRight.CALL
            and contract.expiry.date() == selected_expiry
            and float(contract.strike) >= minimum_strike
        ]

        if not candidates:
            self.debug("Skipped entry: no qualifying OTM call at selected expiration.")
            return

        selected = min(candidates, key=lambda c: (float(c.strike), str(c.symbol)))
        ticket = self.market_order(selected.symbol, 1, tag="Bullish five-minute MA crossover")

        self.entry_order_id = ticket.order_id
        self.debug(
            f"Entry submitted: {selected.symbol} exp {selected.expiry.date()} "
            f"strike {selected.strike}"
        )

    def _check_profit_target(self, data: Slice):
        if self.held_contract is None or self.entry_price is None:
            return

        if self.held_contract not in data.quote_bars:
            return

        quote = data.quote_bars[self.held_contract]
        bid = float(quote.bid.close) if quote.bid is not None else 0.0
        ask = float(quote.ask.close) if quote.ask is not None else 0.0

        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= self.entry_price * 1.50:
            self._submit_exit("50% profit target")
            self.debug(
                f"Profit-target exit submitted: {self.held_contract}, "
                f"midpoint {midpoint:.2f}"
            )

    def _check_time_stop(self):
        if self.held_contract is None or self.held_expiry is None:
            return

        previous_trading_day = self._previous_trading_day(self.held_expiry.date())
        if (
            self.time.date() == previous_trading_day
            and self.time.hour == 15
