class SpyFiveMinuteCallCrossover(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone(TimeZones.NewYork)

        self.spy = self.AddEquity(
            "SPY",
            Resolution.Minute,
            Market.USA,
            fill_forward=False,
            data_normalization_mode=DataNormalizationMode.Raw
        ).Symbol

        self.option = self.AddOption(
            "SPY",
            Resolution.Minute,
            Market.USA,
            fill_forward=False
        )
        self.option.SetFilter(
            -200,
            200,
            timedelta(days=0),
            timedelta(days=730)
        )
        self.option_symbol = self.option.Symbol

        self.fast = SimpleMovingAverage(5)
        self.slow = SimpleMovingAverage(20)

        self.five_minute_consolidator = TradeBarConsolidator(timedelta(minutes=5))
        self.five_minute_consolidator.DataConsolidated += self.OnFiveMinuteBar
        self.SubscriptionManager.AddConsolidator(self.spy, self.five_minute_consolidator)

        self.held_contract = None
        self.held_expiry_date = None
        self.entry_fill_price = None
        self.entry_order_id = None
        self.exit_order_id = None
        self.block_entries_on_date = None

    def OnData(self, slice: Slice):
        self._handle_unexpected_spy_position()
        self._handle_expiration_processing()
        self._handle_time_stop()
        self._handle_profit_target(slice)

    def OnFiveMinuteBar(self, sender, bar: TradeBar):
        # The consolidator receives only actual minute data because fill-forward is disabled.
        # It is anchored to the exchange session clock, so the first RTH bar ends at 09:35.
        prior_ready = self.fast.IsReady and self.slow.IsReady
        prior_fast = self.fast.Current.Value
        prior_slow = self.slow.Current.Value

        self.fast.Update(bar.EndTime, bar.Close)
        self.slow.Update(bar.EndTime, bar.Close)

        if not prior_ready or not self.fast.IsReady or not self.slow.IsReady:
            return

        bullish_crossover = (
            prior_fast <= prior_slow and
            self.fast.Current.Value > self.slow.Current.Value
        )
        if not bullish_crossover:
            return

        end_time = bar.EndTime
        if not self._is_entry_time(end_time):
            return

        self._try_enter_from_current_slice()

    def _try_enter_from_current_slice(self):
        if self.block_entries_on_date == self.Time.date():
            return

        if self.held_contract is not None and self.Portfolio[self.held_contract].Quantity != 0:
            return

        if self._has_open_entry_order():
            return

        if self.Portfolio[self.spy].Quantity != 0:
            return

        current_slice = self.CurrentSlice
        if current_slice is None:
            self.Debug("Entry skipped: no current Slice.")
            return

        chain = self._get_option_chain(current_slice)
        if chain is None:
            self.Debug("Entry skipped: no SPY option chain.")
            return

        spy_price = self.Securities[self.spy].Price
        if spy_price <= 0:
            self.Debug("Entry skipped: invalid SPY price.")
            return

        min_expiry = self.Time.date() + timedelta(days=7)
        contracts = list(chain)

        expirations = sorted({
            contract.Expiry.date()
            for contract in contracts
            if contract.Expiry.date() >= min_expiry
        })
        if not expirations:
            self.Debug("Entry skipped: no expiration at least seven calendar days away.")
            return

        selected_expiry = expirations[0]
        minimum_strike = spy_price * 1.01

        candidates = [
            contract for contract in contracts
            if contract.Right == OptionRight.Call
            and contract.Expiry.date() == selected_expiry
            and contract.Strike >= minimum_strike
        ]

        if not candidates:
            self.Debug("Entry skipped: no qualifying call at selected expiration.")
            return

        selected = min(candidates, key=lambda contract: (contract.Strike, str(contract.Symbol)))
        ticket = self.MarketOrder(selected.Symbol, 1)

        if ticket is None:
            self.Debug("Entry skipped: market order was not created.")
            return

        self.entry_order_id = ticket.OrderId
        self.Debug(
            f"Entry submitted: {selected.Symbol}, expiry {selected_expiry}, "
            f"strike {selected.Strike:.2f}."
        )

    def _handle_profit_target(self, slice: Slice):
        if self.held_contract is None or self.entry_fill_price is None:
            return

        quantity = self.Portfolio[self.held_contract].Quantity
        if quantity <= 0:
            return

        quote_bar = self._get_quote_bar(slice, self.held_contract)
        if quote_bar is None or quote_bar.Bid is None or quote_bar.Ask is None:
            return

        bid = quote_bar.Bid.Close
        ask = quote_bar.Ask.Close
        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= self.entry_fill_price * 1.50:
            self._submit_option_exit("profit target")

    def _handle_time_stop(self):
        if self.held_contract is None or self.held_expiry_date is None:
            return

        if self.Time.hour != 15 or self.Time.minute != 45:
            return

        if self.Time.date() == self._previous_spy_trading_day(self.held_expiry_date):
            self._submit_option_exit("15:45 pre-expiration time stop")

    def _handle_expiration_processing(self):
        if self.held_contract is None or self.held_expiry_date is None:
            return

        if self.Time.date() >= self.held_expiry_date:
            self.block_entries_on_date = self.Time.date()
            self._submit_option_exit("expiration processing")

    def _handle_unexpected_spy_position(self):
        quantity = self.Portfolio[self.spy].Quantity
        if quantity == 0:
            return

        self.block_entries_on_date = self.Time.date()

        if not self.Transactions.GetOpenOrders(self.spy):
            self.Debug(
                f"Unexpected SPY exercise/assignment position ({quantity}); liquidating."
            )
            self.MarketOrder(self.spy, -quantity)

    def _submit_option_exit(self, reason: str):
        if self.held_contract is None:
            return

        quantity = self.Portfolio[self.held_contract].Quantity
        if quantity <= 0:
            return

        if self.exit_order_id is not None:
            existing = self.Transactions.GetOrderById(self.exit_order_id)
            if existing is not None and existing.Status not in [
                OrderStatus.Filled,
                OrderStatus.Canceled,
                OrderStatus.Invalid
            ]:
                return
            self.exit_order_id = None

        for open_order in self.Transactions.GetOpenOrders(self.held_contract):
            self.Transactions.CancelOrder(open_order.Id, f"Replacing exit: {reason}")

        ticket = self.MarketOrder(self.held_contract, -quantity)
        if ticket is not None:
            self.exit_order_id = ticket.OrderId
            self.Debug(f"Exit submitted ({reason}): {self.held_contract}.")

    def OnOrderEvent(self, order_event: OrderEvent):
        if order_event.OrderId == self.entry_order_id:
            if order_event.Status == OrderStatus.Filled:
                self.held_contract = order_event.Symbol
                self.held_expiry_date = order_event.Symbol.ID.Date.date()
                self.entry_fill_price = order_event.FillPrice
                self.entry_order_id = None
                self.Debug(
                    f"Entry filled: {self.held_contract} at {self.entry_fill_price:.2f}."
                )
            elif order_event.Status in [OrderStatus.Canceled, OrderStatus.Invalid]:
                self.entry_order_id = None
                self.Debug(f"Entry order closed without fill: {order_event.Symbol}.")

        if order_event.OrderId == self.exit_order_id:
            if order_event.Status == OrderStatus.Filled:
                self.Debug(
                    f"Exit filled: {order_event.Symbol} at {order_event.FillPrice:.2f}."
                )
                self.exit_order_id = None
                self.held_contract = None
                self.held_expiry_date = None
                self.entry_fill_price = None
            elif order_event.Status in [OrderStatus.Canceled, OrderStatus.Invalid]:
                self.exit_order_id = None
                self.Debug(f"Exit order closed without fill: {order_event.Symbol}.")

    def _has_open_entry_order(self) -> bool:
        if self.entry_order_id is None:
            return False

        order = self.Transactions.GetOrderById(self.entry_order_id)
        if order is None or order.Status in [
            OrderStatus.Filled,
            OrderStatus.Canceled,
            OrderStatus.Invalid
        ]:
            self.entry_order_id = None
            return False

        return True

    def _get_option_chain(self, slice: Slice):
        if slice.OptionChains.ContainsKey(self.option_symbol):
            return slice.OptionChains[self.option_symbol]
        return None

    def _get_quote_bar(self, slice: Slice, symbol: Symbol):
        if slice.QuoteBars.ContainsKey(symbol):
            return slice.QuoteBars[symbol]
        return None

    def _is_entry_time(self, end_time: datetime) -> bool:
        current = end_time.hour * 60 + end_time.minute
        return 9 * 60 + 45 <= current <= 14 * 60 + 30

    def _previous_spy_trading_day(self, expiry_date):
        exchange_hours = self.Securities[self.spy].Exchange.Hours
        candidate = expiry_date - timedelta(days=1)

        while not exchange_hours.IsDateOpen(
            datetime.combine(candidate, datetime.min.time()),
            False
        ):
            candidate -= timedelta(days=1)

        return candidate
